const e = $input.first().json;
const execId = e.execution?.id || 'unknown';
const execUrl = e.execution?.url || `https://jerry-hsieh.app.n8n.cloud/execution/${execId}`;
const wfName = e.workflow?.name || 'Supervisor Daily Report';
const nodeName = e.execution?.lastNodeExecuted || e.execution?.error?.node?.name || '未知節點';
const errMsg = e.execution?.error?.message || '未知錯誤';

const msg = [
  '⚠️ 監工日誌系統發生錯誤',
  '',
  `🔴 工作流程：${wfName}`,
  `❌ 失敗節點：${nodeName}`,
  `📋 錯誤訊息：${errMsg.substring(0, 100)}`,
  '',
  '🔁 點擊重試：',
  execUrl
].join('\n');

const flex = {
  to: 'Ubf65144da2093a2cb9e01528d773413f',
  messages: [{
    type: 'flex',
    altText: '⚠️ 監工日誌系統發生錯誤',
    contents: {
      type: 'bubble',
      header: {
        type: 'box',
        layout: 'vertical',
        contents: [{
          type: 'text',
          text: '⚠️ 系統錯誤通知',
          weight: 'bold',
          size: 'lg',
          color: '#ffffff'
        }],
        backgroundColor: '#d9534f'
      },
      body: {
        type: 'box',
        layout: 'vertical',
        spacing: 'sm',
        contents: [
          { type: 'text', text: `工作流程：${wfName}`, wrap: true, size: 'sm' },
          { type: 'text', text: `失敗節點：${nodeName}`, wrap: true, size: 'sm', color: '#d9534f' },
          { type: 'text', text: `錯誤：${errMsg.substring(0, 120)}`, wrap: true, size: 'xs', color: '#666666' }
        ]
      },
      footer: {
        type: 'box',
        layout: 'vertical',
        contents: [{
          type: 'button',
          style: 'primary',
          color: '#1e90ff',
          action: {
            type: 'uri',
            label: '前往 n8n 重試',
            uri: execUrl
          }
        }]
      }
    }
  }]
};

return [{ json: { payload: JSON.stringify(flex) } }];

// Errors the supervisor form hit on a user's phone (see reportError() in
// index.html). Forwarded to Jerry on LINE; the full report also stays in this
// workflow's execution log.
const r = $input.first().json.body || $input.first().json;
const KIND = {
  photo_upload_failed: '📷 照片上傳失敗',
  photo_unreadable: '🖼️ 照片無法讀取',
  photos_skipped: '⏭️ 使用者略過失敗的照片送出',
  submit_failed: '📨 報告送出失敗',
  options_load_failed: '📋 下拉選項載入失敗',
  js_error: '🐞 表單程式錯誤',
};
const cut = (v, n) => String(v ?? '').slice(0, n);
const when = r.at ? new Date(r.at).toLocaleString('zh-TW', { hour12: false }) : '-';
const ua = String(r.userAgent || '');
const device = (ua.match(/\(([^)]+)\)/) || [])[1] || ua;

const lines = [
  `⚠️ 表單錯誤回報：${KIND[r.kind] || r.kind || '未知'}`,
  '',
  `👤 填寫者：${r.lineDisplayName || '-'}（${r.supervisor || '未選'}）`,
  `🏗️ 廠商：${r.contractor || '-'}`,
  `📁 工程：${r.projectName || '-'}`,
  `📅 報告日期：${r.reportDate || '-'}`,
  `🕒 發生時間：${when}`,
  `📶 網路：${r.online === false ? '離線' : '連線中'}　語言：${r.language || '-'}　照片：${r.photoCount ?? '-'} 張`,
  '',
  `❌ ${cut(r.message, 300)}`,
];
const extra = r.extra || {};
if (Array.isArray(extra.photos)) {
  lines.push('', '失敗的照片：');
  extra.photos.slice(0, 10).forEach(p => lines.push(`• #${p.index} ${cut(p.name, 40)}（${p.type || '?'}, ${p.sizeKB}KB）\n  ${cut(p.error, 150)}`));
}
if (Array.isArray(extra.files)) {
  lines.push('', '無法讀取的照片：');
  extra.files.slice(0, 10).forEach(f => lines.push(`• ${cut(f.name, 40)}（${f.type || '?'}, ${f.sizeKB}KB）\n  ${cut(f.reason, 150)}`));
}
if (extra.source) lines.push('', `位置：${cut(extra.source, 200)}`);
if (extra.stack) lines.push(`Stack：${cut(extra.stack, 400)}`);
lines.push('', `📱 ${cut(device, 150)}`);
if (r.submissionId) lines.push(`🆔 ${r.submissionId}`);

const payload = {
  to: 'Ubf65144da2093a2cb9e01528d773413f',
  messages: [{ type: 'text', text: cut(lines.join('\n'), 4900) }],
};
return [{ json: { payload: JSON.stringify(payload) } }];
